<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="stylesheet" href="<?=e(url('public/assets/css/app.css'))?>"></head>
<body class="login-page"><main class="login-card"><div class="brand-mark">پ</div><h1><?=e(t('app_name'))?></h1><p class="muted">ورود امن با رمز یک‌بارمصرف</p>
<div class="login-tabs"><button type="button" class="active" data-login-mode="otp">ورود با پیامک</button><button type="button" data-login-mode="password">ورود با رمز عبور</button></div>
<form id="login-form"><label>شماره موبایل<input id="mobile" type="tel" inputmode="numeric" maxlength="11" placeholder="09123456789" autocomplete="username" required></label><div id="otp-wrap" hidden><label>کد تأیید<input id="otp" type="text" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></label></div><div id="password-wrap" hidden><label>رمز عبور<input id="password" type="password" maxlength="128" autocomplete="current-password"></label></div><button id="login-button" class="btn primary" type="submit"><?=e(t('send_code'))?></button><p id="message" class="form-message" aria-live="polite"></p></form>
</main><script>window.APP={base:<?=json_encode(rtrim(url(''),'/'))?>}</script><script src="<?=e(url('public/assets/js/login.js'))?>"></script></body></html>
